#[test]
fn provision_token_verbs_parse() {
    use losos_registrar::opts::{ProvisionOpts, TokenVerb};
    let verb = |args: &[&str]| {
        let all: Vec<String> = ["provision", "token"]
            .iter()
            .chain(args)
            .map(|s| s.to_string())
            .collect();
        match parse(all) {
            Ok(Mode::Provision(ProvisionOpts::Token { edge, verb, .. })) => Ok((edge, verb)),
            Ok(_) => panic!("expected provision token"),
            Err(e) => Err(format!("{e}")),
        }
    };
    let (edge, create) = verb(&[
        "create",
        "--edge",
        "https://register.example.org/",
        "--name",
        "laptop",
        "--key",
        "ABCD",
    ])
    .unwrap();
    assert_eq!(edge, "https://register.example.org");
    assert_eq!(
        create,
        TokenVerb::Create {
            name: "laptop".into(),
            fingerprint: "ABCD".into(),
            scope: "full".into(),
            expires_in_days: Some(90),
        }
    );
    let (_, never) = verb(&[
        "create",
        "--edge",
        "https://e",
        "--name",
        "ci",
        "--key",
        "AB",
        "--scope",
        "read",
        "--never-expires",
    ])
    .unwrap();
    assert!(matches!(
        never,
        TokenVerb::Create {
            expires_in_days: None,
            ..
        }
    ));
    assert!(verb(&[
        "create",
        "--edge",
        "https://e",
        "--name",
        "x",
        "--key",
        "AB",
        "--scope",
        "root"
    ])
    .is_err());
    assert_eq!(
        verb(&["list", "--edge", "https://e"]).unwrap().1,
        TokenVerb::List
    );
    assert_eq!(
        verb(&["revoke", "--edge", "https://e", "0a1b2c3d"])
            .unwrap()
            .1,
        TokenVerb::Revoke {
            id: "0a1b2c3d".into()
        }
    );
    assert!(verb(&["revoke", "--edge", "https://e"]).is_err());
}

#[test]
fn monero_takes_its_wallet_service_and_node_beside_usdc() {
    const SOL: &str = "network=solana-devnet,rpc=/run/c/usdc-rpc-solana-devnet,treasury=5ZWj7a1f8tWkjBESHKgrLmXshuXxqeY9SYcfbshpAqPG";
    const XMR: [&str; 6] = [
        "--market-xmr-wallet-rpc",
        "http://127.0.0.1:18083",
        "--market-xmr-login-file",
        "/var/lib/losos-monero-wallet/rpc-login",
        "--market-xmr-daemon-rpc",
        "http://127.0.0.1:18081",
    ];
    let args = |usdc: bool, currency: &'static str, xmr: &[&'static str]| {
        let mut args = vec!["--market-currency", currency];
        if usdc {
            args.extend(["--market-usdc", SOL]);
        }
        args.extend(xmr);
        args.extend(MARKET_FLAGS);
        serve_args(&args)
    };
    let opts = parse(args(true, "usd", &XMR)).expect("parses");
    let Mode::Serve(opts) = opts else {
        panic!("not serve")
    };
    let xmr = opts.market.expect("market").xmr.expect("monero on");
    assert_eq!(xmr.wallet_rpc, "http://127.0.0.1:18083");
    assert_eq!(xmr.login_file, "/var/lib/losos-monero-wallet/rpc-login");
    assert_eq!(xmr.daemon_rpc, "http://127.0.0.1:18081");

    // Priced in dollars beside USDC, both endpoints required, neither with
    // a login in it.
    assert!(parse(args(false, "usd", &XMR)).is_err());
    assert!(parse(args(true, "eur", &XMR)).is_err());
    assert!(parse(args(true, "usd", &XMR[..4])).is_err());
    assert!(parse(args(true, "usd", &[XMR[0], XMR[1], XMR[4], XMR[5]])).is_err());
    let mut leaky = XMR;
    leaky[1] = "http://losos:pw@127.0.0.1:18083";
    assert!(parse(args(true, "usd", &leaky)).is_err());
}

#[test]
fn zcash_takes_mainnet_servers_of_two_operators_beside_usdc() {
    const SOL: &str = "network=solana-devnet,rpc=/run/c/usdc-rpc-solana-devnet,treasury=5ZWj7a1f8tWkjBESHKgrLmXshuXxqeY9SYcfbshpAqPG";
    const ZEC: [&str; 4] = [
        "--market-zec-server",
        "https://zec-node.cakewallet.com:443",
        "--market-zec-server",
        "https://na.zec.rocks:443",
    ];
    let args = |usdc: bool, currency: &'static str, zec: &[&'static str]| {
        let mut args = vec!["--market-currency", currency];
        if usdc {
            args.extend(["--market-usdc", SOL]);
        }
        args.extend(zec);
        args.extend(MARKET_FLAGS);
        serve_args(&args)
    };
    let zec_of = |args| {
        let Mode::Serve(opts) = parse(args).expect("parses") else {
            panic!("not serve")
        };
        opts.market.expect("market").zec
    };
    let zec = zec_of(args(true, "usd", &ZEC)).expect("zcash on");
    assert_eq!(
        zec.servers,
        [
            "https://zec-node.cakewallet.com:443",
            "https://na.zec.rocks:443"
        ]
    );
    // Mainnet unless a test edge names another network.
    assert_eq!(zec.network, losos_registrar::zcash::Network::Main);
    let mut regtest = ZEC.to_vec();
    regtest.extend(["--market-zec-network", "regtest"]);
    assert_eq!(
        zec_of(args(true, "usd", &regtest)).unwrap().network,
        losos_registrar::zcash::Network::Regtest
    );
    assert!(zec_of(args(true, "usd", &[])).is_none());

    // Priced in dollars beside USDC; two operators, not two servers of one;
    // no login in a URL; a network the edge knows.
    assert!(parse(args(false, "usd", &ZEC)).is_err());
    assert!(parse(args(true, "eur", &ZEC)).is_err());
    assert!(parse(args(true, "usd", &ZEC[..2])).is_err());
    let one_operator = [
        "--market-zec-server",
        "https://na.zec.rocks:443",
        "--market-zec-server",
        "https://eu.zec.rocks:443",
    ];
    assert!(parse(args(true, "usd", &one_operator)).is_err());
    let mut leaky = ZEC;
    leaky[1] = "https://user:pw@zec-node.cakewallet.com:443";
    assert!(parse(args(true, "usd", &leaky)).is_err());
    let mut unknown = ZEC.to_vec();
    unknown.extend(["--market-zec-network", "devnet"]);
    assert!(parse(args(true, "usd", &unknown)).is_err());
}

const BINANCE_KEY: &str = "";

/// The onramp's flags, with Binance's key written to a file once.
fn onramp() -> Vec<&'static str> {
    static KEY: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    let key = KEY.get_or_init(|| {
        let path = std::env::temp_dir().join(format!("losos-binance-{}.pub", std::process::id()));
        let pem = format!("-----BEGIN PUBLIC KEY-----\n{BINANCE_KEY}\n-----END PUBLIC KEY-----\n");
        std::fs::write(&path, pem).unwrap();
        path.to_string_lossy().into_owned()
    });
    vec![
        "--onramp-binance-api",
        "https://api.example.binance.com",
        "--onramp-binance-client-id",
        "losos",
        "--onramp-binance-key-file",
        "/run/credentials/losos-registrar.service/binance-connect-key",
        "--onramp-binance-token-file",
        "/run/credentials/losos-registrar.service/binance-connect-token",
        "--onramp-binance-webhook-key-file",
        key,
    ]
}

